//! `is_frame_line` — pure stack-frame predicate (per-method record of the pty_faults parser).
//! Composes [`is_numbered_frame`] for the Rust-backtrace numbered-frame shape.

use super::is_numbered_frame;

/// Whether a line looks like a stack frame / trailing note that belongs to the head above it.
pub(crate) fn is_frame_line(l: &str) -> bool {
    let t = l.trim_start();
    if t.is_empty() {
        return false;
    }
    t.starts_with("at ")            // JS/Node/JVM: "at foo (app.js:1:1)"
        || t.starts_with("note:")   // Rust: "note: run with RUST_BACKTRACE=1 ..."
        || t.starts_with("stack backtrace")
        || t.starts_with("goroutine ") // Go
        || t.contains(".go:")
        || t.contains(".rs:")
        || t.contains(".js:")
        || t.contains(".ts:")
        || t.contains(".py:")
        || is_numbered_frame(t)     // Rust backtrace "  12: core::..." / Python "File ..., line N"
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn recognizes_mainstream_stack_frame_shapes() {
        assert!(is_frame_line("    at getUser (/app/src/user.js:12:20)"));
        assert!(is_frame_line("note: run with `RUST_BACKTRACE=1`"));
        assert!(is_frame_line("  12: core::panicking::panic"), "numbered backtrace frame");
        assert!(is_frame_line("   thread panicked at main.rs:5:1"), "contains a .rs: location");
        assert!(is_frame_line("goroutine 1 [running]:"));
    }

    #[test]
    fn ordinary_lines_are_not_frames() {
        assert!(!is_frame_line("GET /api/users 200"));
        assert!(!is_frame_line(""));
        assert!(!is_frame_line("   "));
    }
}
